    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        tenTruong      = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        await LoadMeta();
        await LoadData();
    }

    // ── LOAD META (Khối / Lớp) ──
    private async Task LoadMeta()
    {
        if (string.IsNullOrEmpty(maTruongBo)) return;
        try
        {
            var taskKhoi = TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc ?? "1");
            var taskLop  = TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc ?? "1", selectedNamHoc ?? "");
            await Task.WhenAll(taskKhoi, taskLop);
            KhoiList        = taskKhoi.Result;
            AllLopList      = taskLop.Result;
            FilteredLopList = AllLopList.ToList();
        }
        catch (Exception ex) { Console.WriteLine($"LoadMeta error: {ex.Message}"); }
    }

    // ── LOAD DANH SÁCH HỌC SINH ──
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;

        isLoading = true;
        StateHasChanged();

        try
        {
            AllHocSinh = await TruongService.hGetDanhSachHocSinh(
                maTruongBo, selectedCapHoc ?? "1", selectedNamHoc);

            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadData error: {ex.Message}");
            await ShowToast("Lỗi tải danh sách học sinh!", "error");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // ── FILTER ──
    private void ApplyFilter()
    {
        if (AllHocSinh == null) { FilteredList = new(); DisplayList = new(); StateHasChanged(); return; }

        var result = AllHocSinh.AsEnumerable();

        // Lọc theo khối
        if (!string.IsNullOrEmpty(selectedMaKhoi))
            result = result.Where(h => h.MaKhoiBo == selectedMaKhoi);

        // Lọc theo lớp
        if (selectedIdLop.HasValue && selectedIdLop > 0)
            result = result.Where(h => h.IdLopBo == selectedIdLop);

        // Lọc theo hình thức học tập
        if (filterHinhThuc > 0)
            result = result.Where(h => h.IdHinhThucHopTap == filterHinhThuc);

        // Tìm kiếm text
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var t = searchTerm.Trim();
            result = result.Where(h =>
                (h.HoTen?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (h.MaHsSo?.Contains(t, StringComparison.OrdinalIgnoreCase) == true));
        }

        // Sắp xếp: bán trú lên trên, rồi theo lớp và tên
        FilteredList = result
            .OrderByDescending(h => h.IdHinhThucHopTap == 2)
            .ThenBy(h => h.TenLop)
            .ThenBy(h => h.HoTen)
            .ToList();

        currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    private void BuildPagedList()
    {
        DisplayList = FilteredList
            .Skip((currentPage - 1) * pageSize)
            .Take(pageSize)
            .ToList();
    }

    // ── PAGINATION HANDLERS ──
    private void OnPageChanged(int page)
    {
        currentPage = page;
        BuildPagedList();
        StateHasChanged();
    }

    private void OnPageSizeChanged(int size)
    {
        pageSize    = size;
        currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    // ── FILTER EVENTS ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        selectedMaKhoi  = e.Value?.ToString() ?? "";
        selectedIdLop   = null;
        FilteredLopList = string.IsNullOrEmpty(selectedMaKhoi)
            ? AllLopList.ToList()
            : AllLopList.Where(l => l.MaKhoiBo == selectedMaKhoi).ToList();
        ApplyFilter();
        await Task.CompletedTask;
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        selectedIdLop = int.TryParse(e.Value?.ToString(), out var id) ? id : null;
        ApplyFilter();
        await Task.CompletedTask;
    }

    // ── ĐỔI HÌNH THỨC HỌC TẬP ──
    private void AskChangeHinhThuc(HocSinhDTO student)
    {
        _confirmStudent = student;
        _showConfirm    = true;
    }

    private void CloseConfirm()
    {
        _showConfirm    = false;
        _confirmStudent = null;
    }

    private async Task ExecuteChangeHinhThuc()
    {
        if (_confirmStudent == null) return;
        _isProcessing = true;
        StateHasChanged();

        try
        {
            int newHinhThuc = _confirmStudent.IdHinhThucHopTap == 1 ? 2 : 1;

            // Gọi service cập nhật hình thức học tập
            await TruongService.hUpdateHinhThucHopTap(_confirmStudent.MaHsSo, newHinhThuc);

            // Cập nhật local
            _confirmStudent.IdHinhThucHopTap = newHinhThuc;
            ApplyFilter();

            string msg = newHinhThuc == 2 ? "Đã chuyển sang bán trú!" : "Đã chuyển về bình thường!";
            await ShowToast(msg, "success");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExecuteChangeHinhThuc error: {ex.Message}");
            await ShowToast("Cập nhật thất bại, vui lòng thử lại!", "error");
        }
        finally
        {
            _isProcessing   = false;
            _showConfirm    = false;
            _confirmStudent = null;
            StateHasChanged();
        }
    }

    // ── EXCEL STATE ──
