    private int                    _importStep      = 1;  // 1=chọn file, 2=preview, 3=xong
    private List<ImportRow>        _importRows      = new();
    private string                 _importError     = "";
    private int                    _importSuccessCount = 0;

    record ImportRow(
        string MaHsSo, string HoTen, string TenLop,
        int OldHinhThuc, int NewHinhThuc,
        bool IsValid, bool Changed, string ErrorMsg
    );

    // ── EXPORT EXCEL ──
    private async Task ExportExcel()
    {
        if (AllHocSinh == null || AllHocSinh.Count == 0) return;

        try
        {
            using var wb = new XLWorkbook();
            var ws = wb.Worksheets.Add("Danh sách bán trú");

            // Tiêu đề sheet
            ws.Cell(1, 1).Value = $"DANH SÁCH HỌC SINH BÁN TRÚ - NĂM HỌC {selectedNamHoc} - {tenTruong}";
            ws.Range(1, 1, 1, 4).Merge().Style
                .Font.SetBold(true).Font.SetFontSize(13)
                .Alignment.SetHorizontal(XLAlignmentHorizontalValues.Center)
                .Fill.SetBackgroundColor(XLColor.FromHtml("#6366f1"))
                .Font.SetFontColor(XLColor.White);

            // Header cột
            var headers = new[] { "Mã học sinh", "Học và tên", "Lớp", "Hình thức học" };
            for (int c = 0; c < headers.Length; c++)
            {
                var cell = ws.Cell(2, c + 1);
                cell.Value = headers[c];
                cell.Style
                    .Font.SetBold(true)
                    .Fill.SetBackgroundColor(XLColor.FromHtml("#e0e7ff"))
                    .Alignment.SetHorizontal(XLAlignmentHorizontalValues.Center)
                    .Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            }

            // Dữ liệu
            var sorted = AllHocSinh
                .OrderByDescending(h => h.IdHinhThucHopTap == 2)
                .ThenBy(h => h.TenLop)
                .ThenBy(h => h.HoTen)
                .ToList();

            for (int i = 0; i < sorted.Count; i++)
            {
                var h   = sorted[i];
                int row = i + 3;
                ws.Cell(row, 1).Value = h.MaHsSo;
                ws.Cell(row, 2).Value = h.HoTen;
                ws.Cell(row, 3).Value = h.TenLop;
                ws.Cell(row, 4).Value = h.IdHinhThucHopTap == 2 ? "Bán trú" : "Bình thường";

                // Tô màu hàng bán trú
                if (h.IdHinhThucHopTap == 2)
                    ws.Range(row, 1, row, 4).Style.Fill.SetBackgroundColor(XLColor.FromHtml("#f0fdf4"));

                // Viền
                ws.Range(row, 1, row, 4).Style.Border.SetOutsideBorder(XLBorderStyleValues.Hair);
            }

            // Auto fit
            ws.Column(1).Width = 18;
            ws.Column(2).Width = 30;
            ws.Column(3).Width = 10;
            ws.Column(4).Width = 16;

            // Ghi ra MemoryStream và download
            using var ms = new System.IO.MemoryStream();
            wb.SaveAs(ms);
            var bytes = ms.ToArray();
            var base64 = Convert.ToBase64String(bytes);
            var fileName = $"BanTru_{selectedNamHoc}_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";

            await JS.InvokeVoidAsync("downloadFileFromBase64", fileName, base64);

            await ShowToast("Xuất Excel thành công!", "success");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExportExcel error: {ex.Message}");
            await ShowToast("Xuất Excel thất bại!", "error");
        }
    }

