    private async Task OnFileSelected(InputFileChangeEventArgs e)
    {
        _importError = "";
        var file = e.File;
        if (file == null) return;

        if (!file.Name.EndsWith(".xlsx", StringComparison.OrdinalIgnoreCase) &&
            !file.Name.EndsWith(".xls",  StringComparison.OrdinalIgnoreCase))
        {
            _importError = "Chỉ chấp nhận file .xlsx hoặc .xls";
            StateHasChanged();
            return;
        }

        try
        {
            // Map nhanh MaHsSo → học sinh hiện tại
            var lookup = (AllHocSinh ?? new()).ToDictionary(h => h.MaHsSo, StringComparer.OrdinalIgnoreCase);

            _importRows = new();
            using var ms = new System.IO.MemoryStream();
            await file.OpenReadStream(maxAllowedSize: 5 * 1024 * 1024).CopyToAsync(ms);
            ms.Position = 0;

            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            using var ep  = new ExcelPackage(ms);
            var sheet = ep.Workbook.Worksheets[0];
            if (sheet == null)
            {
                _importError = "File Excel không có sheet nào!";
                StateHasChanged();
                return;
            }

            int startRow = 2;  // Bỏ header trên cùng
            // Tìm dòng dữ liệu thực sự (bỏ dòng tiêu đề 2 dòng)
            if (sheet.Dimension == null || sheet.Dimension.Rows < 3)
            {
                _importError = "File không có dữ liệu!";
                StateHasChanged();
                return;
            }

            for (int row = 3; row <= sheet.Dimension.Rows; row++)
            {
                var maHsSo  = sheet.Cells[row, 1].Text?.Trim();
                var hoTen   = sheet.Cells[row, 2].Text?.Trim() ?? "";
                var tenLop  = sheet.Cells[row, 3].Text?.Trim() ?? "";
                var hinhThucStr = sheet.Cells[row, 4].Text?.Trim() ?? "";

                if (string.IsNullOrEmpty(maHsSo)) continue;

                int newHinhThuc = hinhThucStr.Contains("Bán", StringComparison.OrdinalIgnoreCase)
                               || hinhThucStr.Contains("ban", StringComparison.OrdinalIgnoreCase)
                               || hinhThucStr == "2" ? 2 : 1;

                if (!lookup.TryGetValue(maHsSo, out var hs))
                {
                    _importRows.Add(new ImportRow(maHsSo, hoTen, tenLop, 0, newHinhThuc,
                        false, false, "Không tìm thấy mã HS"));
                    continue;
                }

                bool changed = hs.IdHinhThucHopTap != newHinhThuc;
                _importRows.Add(new ImportRow(
                    maHsSo,
                    string.IsNullOrEmpty(hoTen) ? hs.HoTen : hoTen,
                    string.IsNullOrEmpty(tenLop) ? hs.TenLop : tenLop,
                    hs.IdHinhThucHopTap,
                    newHinhThuc,
                    true, changed, ""
                ));
            }

            if (_importRows.Count == 0)
            {
                _importError = "Không đọc được dữ liệu nào từ file!";
                StateHasChanged();
                return;
            }

            _importStep = 2;
        }
        catch (Exception ex)
        {
            _importError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        StateHasChanged();
    }

    private async Task ExecuteImport()
    {
        var toUpdate = _importRows.Where(r => r.IsValid && r.Changed).ToList();
        if (!toUpdate.Any()) return;

        _isProcessing = true;
        StateHasChanged();

        try
        {
            int ok = 0;
            foreach (var row in toUpdate)
            {
                try
                {
                    await TruongService.hUpdateHinhThucHopTap(row.MaHsSo, row.NewHinhThuc);
                    // Cập nhật local
                    var hs = AllHocSinh?.FirstOrDefault(h => h.MaHsSo == row.MaHsSo);
                    if (hs != null) hs.IdHinhThucHopTap = row.NewHinhThuc;
                    ok++;
                }
                catch { /* bỏ qua học sinh bị lỗi */ }
            }

            _importSuccessCount = ok;
            _importStep = 3;
            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExecuteImport error: {ex.Message}");
            await ShowToast("Import thất bại!", "error");
        }
        finally
        {
            _isProcessing = false;
            StateHasChanged();
        }
    }

